function solve(n, edges, source) {
  // Dijkstra sederhana O(n²): selalu proses simpul terdekat yang belum final.
  const jarak = Array(n).fill(Infinity)
  const selesai = Array(n).fill(false)
  jarak[source] = 0
  for (let k = 0; k < n; k++) {
    let u = -1
    for (let i = 0; i < n; i++) {
      if (!selesai[i] && (u === -1 || jarak[i] < jarak[u])) u = i
    }
    if (jarak[u] === Infinity) break // sisanya tidak terjangkau
    selesai[u] = true
    // Relaksasi: apakah lewat u lebih pendek?
    for (const [a, b, w] of edges) {
      if (a === u && jarak[u] + w < jarak[b]) jarak[b] = jarak[u] + w
    }
  }
  return jarak.map((d) => (d === Infinity ? -1 : d)) // -1 = tidak terjangkau
}
